from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from pathlib import Path
from xml.sax.saxutils import escape
out=Path('public/documents');out.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleLW',fontName='Helvetica-Bold',fontSize=25,leading=30,textColor=colors.HexColor('#203d63'),spaceAfter=13))
styles.add(ParagraphStyle(name='SubLW',fontName='Helvetica',fontSize=9,leading=14,textColor=colors.HexColor('#8294ac'),spaceAfter=17))
styles.add(ParagraphStyle(name='HeadLW',fontName='Helvetica-Bold',fontSize=12,leading=16,textColor=colors.HexColor('#315f98'),spaceBefore=14,spaceAfter=7))
styles.add(ParagraphStyle(name='BodyLW',fontName='Helvetica',fontSize=9.4,leading=15,textColor=colors.HexColor('#52677f'),spaceAfter=8))
styles.add(ParagraphStyle(name='SmallLW',fontName='Helvetica',fontSize=8,leading=12,textColor=colors.HexColor('#7e91a8'),spaceAfter=7))
def p(t,style='BodyLW'):return Paragraph(t,styles[style])
def head(t):return p(t,'HeadLW')
def footer(c,d):
 c.setStrokeColor(colors.HexColor('#dfe7f0'));c.line(44,43,551,43);c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#91a0b4'));c.drawString(44,29,'LENDWISE / SYNTHETIC PRESALES DEMONSTRATION');c.drawRightString(551,29,str(d.page))
def build(name,story):SimpleDocTemplate(str(out/name),pagesize=(595,842),leftMargin=44,rightMargin=44,topMargin=42,bottomMargin=59).build(story,onFirstPage=footer,onLaterPages=footer)
def title(k,t,sub):return [p(k,'SmallLW'),p(t,'TitleLW'),p(sub,'SubLW')]
research=title('D5 / RESEARCH NOTE','Personal-loan origination','Scope: salaried unsecured personal loans at a fictional mid-sized Indian bank. Sources accessed 14 November 2026. Two-page working note for the assignment.')
research += [head('The journey and the people'),p('A relationship or branch team captures the application and consent. Operations checks identity and document completeness. Credit staff assess income, obligations and repayment history against the bank\'s approved lending policy. An authorised officer decides within delegated authority; operations completes sanction, agreement and repayment formalities before releasing funds. This role mapping is a proposed operating model to validate with the customer, rather than a claim about one bank\'s internal organisation.'),p('For this personal-loan scope, property valuation and CERSAI collateral checks are not part of the main path. The assignment lists multiple possible external sources; they should be selected for relevance rather than included indiscriminately.'),head('Evidence before eligibility'),p('RBI\'s Commercial Banks - Credit Facilities Directions require relevant borrower economic-profile information, including age, occupation and income, before extending a digital loan, with records for audit. Its digital-lending provisions also address need-based data collection and explicit consent with an audit trail. [1]'),p('ICICI Bank\'s public pages illustrate the types of evidence used: identity/residence evidence, salary slips and salary-credit bank statements. Documentation differs by profile and channel. Its documentation and eligibility pages describe different salary-slip periods, which reinforces the need to retrieve the applicable product/channel policy instead of assuming one universal checklist. [2,3]'),head('The checks and the decision'),p('The assessment should consider verified income, current obligations, employment continuity, bureau history, age and product terms. ICICI\'s eligibility guidance describes these factors and distinguishes a calculator estimate from the bank\'s final internal assessment. [3] A missing document should create an information request; inconsistent evidence should create a review task, not an unsupported fraud accusation.'),p('In Lendwise, the EMI and obligation ratio are calculated deterministically. The configured ratio is (existing monthly EMIs + proposed EMI) / verified net income. All numeric thresholds, including the 50% limit, 750 pass-score band and INR 25,000 income floor, are fictional bank assumptions, not RBI personal-loan mandates.'),head('Sanction is not disbursement'),p('Approval records the credit decision; sanction communicates the proposed terms. Acceptance, agreement and mandate conditions then precede fund release. ICICI notes that additional confirmations or mandate setup may be needed after sanction and before disbursement. [2] RBI\'s digital-lending provisions cover borrower disclosures and fund-flow controls. [1] The prototype simulates these stages and does not issue a complete regulatory KFS or move money.'),PageBreak()]
research+=title('D5 / RESEARCH NOTE / CONTINUED','Where the demo adds value','Research conclusions, assumptions and validation plan.')
research += [head('Turnaround time: distinguish target from evidence'),p('There is no single turnaround time established by the sources reviewed for all applicants and channels. Existing-customer/pre-approved paths and document-heavy cases should not share an unconditional promise. In the demo, "review within 2 working days after complete evidence" is an illustrative service target only; it is not a market benchmark, regulatory deadline or measured improvement. Validate actual median and 90th-percentile times with the bank by stage.'),head('Pain points and the proposed response'),p('<b>Scattered records:</b> connect bank exports, original documents and mock external responses using application/customer identifiers. Keep provenance and timestamps rather than overwriting conflicting values.<br/><b>Changing policies:</b> preserve policy version, clause, effective date and amendment relationships; retrieve reviewed rules for the relevant product and date.<br/><b>Document rework:</b> show exactly what is missing and allow resubmission followed by reassessment.<br/><b>New employee uncertainty:</b> provide a guided tour and contextual how-to assistance; keep decision authority with the employee.'),head('Architecture and implementation honesty'),p('The proposed evidence layer combines Cloud Storage originals with BigQuery structured facts and joined assessment views. Google documents object tables as metadata indexes over unstructured files in Cloud Storage. [4] An operational database should own transactional workflow state. The current prototype instead uses browser-local synthetic records; BigQuery, OCR, live model calls and production authentication are not connected.'),head('Conversations and questions still to validate'),p('No banking-practitioner interview has been conducted or attributed in this research. The user supplied handwritten workflow notes; their provenance has not been established. Before final submission, ask a practitioner about delegated approval limits, exception routes, accepted income evidence, bureau-call timing, document rework and actual stage-level turnaround. Credit a conversation only if it takes place.'),head('Primary sources'),p('[1] RBI, Commercial Banks - Credit Facilities Directions, 2025, updated 1 October 2026; Chapter III digital lending. <link href="https://www.rbi.org.in/Scripts/NotificationUser.aspx?Id=13156&amp;Mode=0" color="#315f98">Open RBI directions</link>.','SmallLW'),p('[2] ICICI Bank, Documents Required for Personal Loan; salaried documents and pre-disbursement requirements. <link href="https://www.icici.bank.in/personal-banking/loans/personal-loan/documentation" color="#315f98">Open documentation</link>.','SmallLW'),p('[3] ICICI Bank, Personal Loan Eligibility; factors, calculator limitations and internal assessment. <link href="https://www.icici.bank.in/personal-banking/loans/personal-loan/eligibility" color="#315f98">Open eligibility guidance</link>.','SmallLW'),p('[4] Google Cloud, Introduction to object tables. <link href="https://docs.cloud.google.com/bigquery/docs/object-table-introduction" color="#315f98">Open technical documentation</link>.','SmallLW'),p('Reference demo inspected: <link href="https://pnb-frontend-7kxckvikva-uc.a.run.app/" color="#315f98">PNB Policy Intelligence</link>. Used as inspiration for clause citations, applicability, dates and amendment traceability; its synthetic policy values were not treated as banking authority.','SmallLW')]
build('research-note.pdf',research)
log=title('D6 / AI USAGE LOG','AI-assisted, transparently','Working record as of 14 November 2026. Review and personalise before submitting as your own account.')
log += [head('Tools actually used'),p('ChatGPT/Codex supported planning, source review, implementation, synthetic data generation, tests and document drafts. Browser tools inspected the supplied reference site and exercised the local application. Claude was discussed but has not been used in this build; no Claude usage is claimed.'),head('Representative requests and how they shaped the work'),p('<b>"What and how do we store?"</b> Led to a preserved-original / validated-fact / assessment-view lakehouse story.<br/><b>"One agent ... is enough?"</b> Led to one assistant with explicit retrieval, calculation and navigation tools, with employee control over decisions.<br/><b>"Make these rules configurable by bank."</b> Led to draft validation, a simulated reviewer activation step, versioned policy values and stale-assessment blocking.<br/><b>"Teach specific things ... walk through the features."</b> Led to an Employee Guide mode with a guided tour and permitted app actions.<br/><b>"Next.js and shadcn components ... minimal and effective."</b> Led to the officer workspace using Next.js, Tailwind, Radix primitives and shadcn-style component patterns.'),head('What worked and what needed correction'),p('AI accelerated the first implementation, consistent sample cases and test drafting. Source review corrected an overly broad interpretation of the INR 60,000 OTP e-KYC limit during planning. The supplied reference website was reviewed after the user explicitly asked; it should have been inspected earlier. Browser testing exposed an over-broad keyword match for "rate" inside unrelated words; retrieval was changed to whole-word matching and a relevance cutoff. Build checks caught syntax issues and an older local Node/ESM compatibility issue; both were resolved.'),head('Verification and limits'),p('Domain tests cover scenario outcomes, EMI calculations, missing evidence, policy snapshots, configuration validation and retrieval relevance. Browser QA exercises the officer workflow and source-backed Q&amp;A. The in-app assistant currently uses local retrieval and scripted actions, not a live model. BigQuery and OCR remain proposed integrations. All applicant and external-response data is synthetic. No interview or production performance claim is fabricated.'),head('Time saved and ownership'),p('Time saved has not been measured against a manual baseline, so no numeric estimate is claimed. The user supplied the product direction, configurable-policy requirement and employee-onboarding concept. AI produced implementation and draft content. The candidate should review the source material, explain the design tradeoffs, test the final version and record any later tool use or practitioner conversations before submission.')]
build('ai-usage-log.pdf',log)
policy=title('SYNTHETIC BANK POLICY / PL-V1','Personal Loan Policy','Fictional Meridian Bank. Effective 14 November 2026. Demo assumptions only; not official bank policy, regulatory guidance or a lending offer.')
policy += [head('2. Applicant eligibility'),p('<b>2.1 Age:</b> minimum 21 at application and maximum 60 at final repayment.<br/><b>2.2 Income:</b> verified net monthly income at least INR 25,000.<br/><b>2.3 Employment:</b> 12 months total employment and 6 months with current employer. Shorter history requires review. Scope is salaried applicants only.'),head('3. Product terms'),p('<b>3.1 Amount:</b> INR 50,000 to INR 10 lakh.<br/><b>3.2 Tenure:</b> 12 to 60 months, subject to maturity-age limit.<br/><b>3.3 Rate:</b> illustrative fixed annual interest rate 12%, reducing-balance monthly EMI. Fees are not modelled. A real offer would require complete APR/fee and KFS disclosures.'),head('4. Credit and affordability'),p('<b>4.1 Bureau:</b> score 750+ meets the score criterion; 700-749 requires review; below 700 recommends decline. No score or a current overdue flag requires review.<br/><b>4.2 Obligation ratio:</b> existing monthly EMIs plus proposed EMI must be no more than 50% of verified net monthly income. Failure defaults to review.<br/><b>4.3 Consistency:</b> declared income differing from verified salary credits by more than 10% requires review; it is not proof of fraud.'),head('5. Evidence requirements'),p('<b>5.1 Documents and identity:</b> identity evidence, three months of salary slips and six months of bank statements are required for this demo. Missing evidence or incomplete mock identity verification blocks approval. Applicant consent is simulated. No real government identifiers are collected.'),head('6. Workflow and service target'),p('<b>6.1 Timeline:</b> illustrative review target is 2 working days after complete evidence and checks. This is not a guarantee, measured result or regulatory deadline.<br/><b>6.2 Authority:</b> the credit officer reviews evidence and records the final decision and reason. A review recommendation needs an exception justification if approved. A pending or stale assessment cannot be approved. Approval precedes sanction; acceptance, agreement and mandate precede simulated disbursement.'),head('7. Configuration and traceability'),p('Policy admins may edit supported numerical thresholds and failure routes. A separate simulated reviewer activates a validated version. The current app activates immediately; future-dated scheduling is not implemented. Previous assessment snapshots remain available in the audit trail. Final employee approval and evidence requirements cannot be removed through these settings. This file records v1; the app displays the active configuration after later changes.','SmallLW')]
build('sample-personal-loan-policy.pdf',policy)
print('Created research note, AI usage log and sample policy.')
